const raw = $json.input !== undefined ? $json.input : $json;

let parsed;
if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw );
  } catch(e) {
    parsed = { content: raw };
  }
} else {
  parsed = raw;
}

let title = (
  parsed.title ||
  parsed.query ||
  $json.title ||
  'Untitled'
).replace(/^#+\s*/, '').trim();

let content =
  parsed.content ||
  parsed.text ||
  parsed.output ||
  parsed.article ||
  $json.content ||
  '';

if (typeof content === 'string' && content.trim().startsWith('{')) {
  try {
    const inner = JSON.parse(content);
    content = inner.content || inner.text || inner.output || content;
  } catch(e) {}
}

if (typeof content === 'object' && content !== null) {
  content = content.content || content.text || content.output || JSON.stringify(content);
}

content = String(content || '').trim();

if (!content) {
  throw new Error('Could not extract content. Raw input received: ' + JSON.stringify($json).substring(0, 300));
}

return [{ json: { title, content } }];

// # → HEADING_1 (24pt bold)
// ## → HEADING_2 (18pt bold)
// ### → HEADING_3 (14pt bold)
// #### → HEADING_4 (12pt bold)
// normal text → NORMAL_TEXT (11pt)
// ─────────────────────────────────────────────────────────

const docNode = $('Create Google Doc').first().json;
const documentId = docNode.documentId || docNode.id;

const inputNode = $('Parse Input').first().json;
const rawContent = inputNode.content || '';

if (!rawContent) {
  throw new Error('Content is empty in Build Requests node');
}

const lines = rawContent.split('\n');
const requests = [];
let cursor = 1;

for (const line of lines) {
  const trimmed = line.trim();

  // Blank line → insert empty paragraph
  if (!trimmed) {
    requests.push({
      insertText: { location: { index: cursor }, text: '\n' }
    });
    cursor += 1;
    continue;
  }

  let text, style, fontSize, bold;

  if (trimmed.startsWith('#### ')) {
    text = trimmed.replace(/^#### /, '');
    style = 'HEADING_4'; fontSize = 12; bold = true;
  } else if (trimmed.startsWith('### ')) {
    text = trimmed.replace(/^### /, '');
    style = 'HEADING_3'; fontSize = 14; bold = true;
  } else if (trimmed.startsWith('## ')) {
    text = trimmed.replace(/^## /, '');
    style = 'HEADING_2'; fontSize = 18; bold = true;
  } else if (trimmed.startsWith('# ')) {
    text = trimmed.replace(/^# /, '');
    style = 'HEADING_1'; fontSize = 24; bold = true;
  } else {
    text = trimmed;
    style = 'NORMAL_TEXT'; fontSize = 11; bold = false;
  }

  const insertedText = text + '\n';
  const endIndex = cursor + insertedText.length;

  // 1. Insert text
  requests.push({
    insertText: {
      location: { index: cursor },
      text: insertedText
    }
  });

  // 2. Paragraph style
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: cursor, endIndex: endIndex },
      paragraphStyle: {
        namedStyleType: style,
        spaceAbove: { magnitude: style !== 'NORMAL_TEXT' ? 14 : 4, unit: 'PT' },
        spaceBelow: { magnitude: style !== 'NORMAL_TEXT' ? 6 : 4, unit: 'PT' }
      },
      fields: 'namedStyleType,spaceAbove,spaceBelow'
    }
  });

  // 3. Text style
  const textStyle = {
    fontSize: { magnitude: fontSize, unit: 'PT' },
    weightedFontFamily: { fontFamily: 'Arial' }
  };
  if (bold) textStyle.bold = true;

  requests.push({
    updateTextStyle: {
      range: { startIndex: cursor, endIndex: endIndex - 1 },
      textStyle: textStyle,
      fields: bold ? 'bold,fontSize,weightedFontFamily' : 'fontSize,weightedFontFamily'
    }
  });

  cursor = endIndex;
}

return [{ json: { documentId, requests } }];
